/** 붓글씨 '두도 피싱' – height 기준으로 크기를 맞춘다 */
@Composable
fun BrandTitle(height: Dp, color: Color = Foam, modifier: Modifier = Modifier) {
    val path = remember { PathParser().parsePathString(TITLE_PATH).toPath() }
    Canvas(modifier.height(height).width(height * (TITLE_W / TITLE_H))) {
        val s = size.height / TITLE_H
        withTransform({ scale(s, s, pivot = Offset.Zero) }) {
            // 살짝 번진 그림자 → 사진 위에서도 또렷하게
            translate(3f, 4f) { drawPath(path, Color.Black.copy(alpha = 0.35f)) }
            drawPath(path, color)
        }
    }
}

/** 제목 + 'DUDO FISHING' */
@Composable
fun BrandBlock(titleHeight: Dp, modifier: Modifier = Modifier) {
    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        BrandTitle(titleHeight)
        Text("D U D O   F I S H I N G", color = Foam.copy(alpha = 0.85f), fontSize = (titleHeight.value / 6.5f).sp,
            fontWeight = FontWeight.Medium, letterSpacing = 1.sp)
    }
}
